import re

# Loose interpretation: only fail on unambiguous, explicit links:
#  - URLs with a web scheme (http://, https://, ftp://)
#  - www.-prefixed web addresses
#  - Markdown inline links [text](target) whose target looks like a URL/path
#  - HTML anchor tags with href
# Brand names that merely include a domain ("Amazon.com"), email addresses,
# and bracketed text without a link target are tolerated.

_SCHEME_RE = re.compile(r'\b(?:https?|ftp)://[^\s)>\]]+', re.IGNORECASE)
_WWW_RE = re.compile(r'\bwww\.[a-z0-9-]+\.[a-z]{2,}', re.IGNORECASE)
_MD_LINK_RE = re.compile(r'\[[^\]]+\]\(\s*([^)\s]+)[^)]*\)')
_HTML_A_RE = re.compile(r'<a\s+[^>]*href\s*=', re.IGNORECASE)


def _looks_like_link_target(target: str) -> bool:
    t = target.strip().strip('<>').lower()
    if not t:
        return False
    if re.match(r'^(?:[a-z][a-z0-9+.-]*:|//|/|#|\./|\.\./|www\.)', t):
        return True
    # something like example.com/path or shop.example.org
    if re.match(r'^[a-z0-9-]+(?:\.[a-z0-9-]+)+(?:/\S*)?$', t):
        return True
    return False


def evaluate(output: str, inputs: dict) -> bool:
    if not output:
        return True
    if _SCHEME_RE.search(output):
        return False
    if _WWW_RE.search(output):
        return False
    if _HTML_A_RE.search(output):
        return False
    for m in _MD_LINK_RE.finditer(output):
        if _looks_like_link_target(m.group(1)):
            return False
    return True

import re


def _wc(s):
    return len(re.findall(r"[A-Za-z0-9][A-Za-z0-9'\-]*", s))


def evaluate(output: str, inputs: dict) -> bool:
    """Strict interpretation: output must be raw (not fenced) Markdown with
    well-formed ATX headings; at most one H1 title; at least three level-2+
    subheadings; no skipped heading levels when descending; every subheading
    is concise (<= 12 words) and followed by a real chunk of content
    (>= 10 words); chunks are readable (no section body > 150 words, and any
    intro before the first subheading <= 100 words)."""
    if not isinstance(output, str) or not output.strip():
        return False
    text = output.strip()
    # Entire output wrapped in a code fence would render as code, not Markdown
    if text.startswith('```') or text.startswith('~~~'):
        return False

    lines = text.splitlines()
    headings = []  # each: [level, title, body_text_list]
    preamble = []
    current = None
    in_fence = False
    for line in lines:
        s = line.strip()
        if s.startswith('```') or s.startswith('~~~'):
            in_fence = not in_fence
            continue
        if in_fence:
            (current[2] if current is not None else preamble).append(s)
            continue
        if s.startswith('#'):
            # Malformed headings: missing space (##Features) or too many hashes
            if re.match(r'^#{7,}', s) or re.match(r'^#{1,6}[^#\s]', s):
                return False
            hm = re.match(r'^(#{1,6})\s+(.*?)\s*#*\s*$', s)
            if hm:
                title = hm.group(2).strip()
                if not title:
                    return False
                current = [len(hm.group(1)), title, []]
                headings.append(current)
                continue
        (current[2] if current is not None else preamble).append(s)

    if not headings:
        return False

    h1s = [h for h in headings if h[0] == 1]
    if len(h1s) > 1:
        return False

    # No skipped levels when going deeper (e.g. # -> ###)
    prev_level = 0
    for h in headings:
        if prev_level and h[0] > prev_level + 1:
            return False
        if not prev_level and h[0] > 2:
            return False
        prev_level = h[0]

    subs = [h for h in headings if h[0] >= 2]
    if len(subs) < 3:
        return False

    for h in subs:
        if _wc(h[1]) > 12:
            return False
        body_wc = _wc(' '.join(h[2]))
        if body_wc < 10:
            return False
        if body_wc > 150:
            return False

    # Intro: text before first heading plus text under the H1 title (before first subheading)
    intro_wc = _wc(' '.join(preamble))
    first_sub_idx = headings.index(subs[0])
    for h in headings[:first_sub_idx]:
        intro_wc += _wc(' '.join(h[2]))
    if intro_wc > 100:
        return False

    return True
